/runtime/node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createRecordRepository } from './src/record-repository.js';
import { createDetailWorkspace } from './src/workspace.js';
import { createComplianceReview } from './src/compliance-review.js';
import { createRecentPreview } from './src/recent-preview.js';

function transportHarness() {
  const listeners = new Map();
  const subscriptions = [];
  return {
    subscribe(id, receive) {
      const entry = { id, receive, stopped: false };
      subscriptions.push(entry);
      listeners.set(entry, receive);
      return () => { entry.stopped = true; listeners.delete(entry); };
    },
    emit(id, value) { for (const entry of subscriptions) if (entry.id === id && !entry.stopped) entry.receive(value); },
    active(id) { return subscriptions.filter(x => x.id === id && !x.stopped).length; },
  };
}

const transport = transportHarness();
const repository = createRecordRepository({ transport, seed: { warm: 'cached' } });
const selections = [], details = [];
const workspace = createDetailWorkspace({ repository, renderSelection: x => selections.push(x), renderDetail: x => details.push(x) });
workspace.open('warm');
assert.deepEqual(details, [{ id: 'warm', value: 'cached', source: 'cache' }]);
assert.equal(transport.active('warm'), 1);
transport.emit('warm', 'fresh');
assert.deepEqual(details.at(-1), { id: 'warm', value: 'fresh', source: 'network' });
workspace.open('warm');
assert.equal(transport.active('warm'), 1);
assert.equal(details.at(-1).source, 'cache');
workspace.open('cold');
assert.equal(transport.active('warm'), 0);
assert.equal(transport.active('cold'), 1);
assert.equal(details.some(x => x.id === 'cold'), false);
transport.emit('cold', 'arrived');
assert.deepEqual(details.at(-1), { id: 'cold', value: 'arrived', source: 'network' });
workspace.close();
assert.equal(transport.active('cold'), 0);
assert.deepEqual(selections.at(-1), null);

const reentrantTransport = transportHarness();
const reentrantRepo = createRecordRepository({ transport: reentrantTransport, seed: { a: 1, b: 2 } });
let reentrantWorkspace;
reentrantWorkspace = createDetailWorkspace({
  repository: reentrantRepo, renderSelection() {}, renderDetail() {},
  onDetail(record, navigation) { if (record.id === 'a') navigation.open('b'); },
});
reentrantWorkspace.open('a');
assert.equal(reentrantWorkspace.selection(), 'b');
assert.equal(reentrantTransport.active('a'), 0);
assert.equal(reentrantTransport.active('b'), 1);

const freshTransport = transportHarness();
const freshRepo = createRecordRepository({ transport: freshTransport, seed: { retained: 1 } });
const review = createComplianceReview({ repository: freshRepo, publish() {} });
const preview = createRecentPreview({ repository: freshRepo, publish() {} });
review.inspect('retained');
preview.inspect('retained');
assert.equal(freshTransport.active('retained'), 2);
console.log('detail activation checks passed');
EOF
